-- P12/P13 2026: saída derivada do congelamento 111, sem nova coleta.
-- Floripa mantém volume; nenhum de seus tempos/grupos/cortes/medalhas é publicado.
-- Pódio parcial entre nove provas, onze critérios e empates explícitos.
-- Preserva todos os demais recortes, perfil, totais nacionais e comparativos.
WITH anterior AS(SELECT result->'rows'->0->'payload' AS payload FROM estudo.notebook_runs WHERE id=109 AND frozen AND status='ok' AND NOT truncated AND row_count=1),
origem AS(SELECT result->'rows'->0->'payload' AS dados FROM estudo.notebook_runs WHERE id=111 AND cell_id=309 AND cell_version=1 AND frozen AND status='ok' AND NOT truncated AND row_count=1),
eventos AS(SELECT t,t->>'nome_evento'||' · '||to_char((t->>'data_final')::date,'DD/MM') AS categoria,(t->>'suspeitos_sub2')::integer>0 AS bloqueada FROM origem CROSS JOIN LATERAL jsonb_array_elements(dados->'top10')t),
mapa AS(SELECT column1 AS serie,column2 AS campo,column3 AS tipo FROM(VALUES('maratonas_concluintes','concluintes','contagem'),('maratonas_feminino','feminino','percentual'),('maratonas_masculino','masculino','percentual'),('maratonas_tempo_menor','tempo_menor','tempo'),('maratonas_tempo_medio','tempo_medio','tempo'),('maratonas_tempo_mediano','tempo_mediano','tempo'),('maratonas_sub4_contagem','sub4','contagem'),('maratonas_sub4_percentual','sub4','percentual'),('maratonas_sub3_contagem','sub3','contagem'),('maratonas_sub3_percentual','sub3','percentual'),('maratonas_sub2h30_contagem','sub2h30','contagem'),('maratonas_sub2h30_percentual','sub2h30','percentual'))t),
valores AS(
 SELECT m.serie,e.categoria,e.bloqueada AND m.campo NOT IN('concluintes','feminino','masculino') AS bloqueada,
 CASE WHEN m.tipo='tempo' THEN e.t->>m.campo WHEN m.tipo='percentual' THEN (((e.t->>m.campo)::numeric*100)/(e.t->>'concluintes')::numeric)::text ELSE e.t->>m.campo END AS valor,
 CASE WHEN m.tipo='tempo' THEN (e.t->>'concluintes')::bigint ELSE (e.t->>m.campo)::bigint END AS contagem,
 CASE WHEN m.campo='concluintes' THEN (o.dados->>'top10_soma')::bigint ELSE (e.t->>'concluintes')::bigint END AS denominador,
 m.tipo='tempo' AS tempo FROM eventos e CROSS JOIN mapa m CROSS JOIN origem o
 UNION ALL
 SELECT 'maratonas_'||(g->>'grupo'),e.categoria,e.bloqueada,g->>'tempo_medio',(g->>'incluidos')::bigint,(g->>'denominador')::bigint,true
 FROM origem CROSS JOIN LATERAL jsonb_array_elements(dados->'grupos')g JOIN eventos e ON e.t->>'id_evento'=g->>'id_evento'
), criterios AS(SELECT column1 AS serie,column2 AS direcao FROM(VALUES('maratonas_sub4_contagem','desc'),('maratonas_sub3_contagem','desc'),('maratonas_sub2h30_contagem','desc'),('maratonas_tempo_menor','asc'),('maratonas_tempo_medio','asc'),('maratonas_tempo_mediano','asc'),('maratonas_top10','asc'),('maratonas_top100','asc'),('maratonas_top5pct','asc'),('maratonas_top10pct','asc'),('maratonas_top50pct','asc'))t),
pontuacao AS(SELECT v.*,CASE WHEN c.direcao='desc' THEN -v.valor::numeric ELSE extract(epoch FROM v.valor::time)::numeric END AS escore FROM valores v JOIN criterios c USING(serie) WHERE NOT v.bloqueada),
integridade AS(SELECT count(*) AS valores,count(DISTINCT categoria) AS provas,count(DISTINCT serie) AS criterios FROM pontuacao),
ranks AS(SELECT p.*,rank() OVER(PARTITION BY p.serie ORDER BY p.escore) AS posicao FROM pontuacao p CROSS JOIN integridade i WHERE i.valores=i.provas*11 AND i.criterios=11),
cores AS(SELECT column1 AS cor,column2 AS posicao FROM(VALUES('ouro',1),('prata',2),('bronze',3))t),
medalhas AS(SELECT 'maratonas_medalhas_'||c.cor AS serie,e.categoria,e.bloqueada,count(*) FILTER(WHERE r.posicao=c.posicao)::text AS valor,
 count(*) FILTER(WHERE r.posicao=c.posicao) AS contagem,11::bigint AS denominador,false AS tempo
 FROM eventos e CROSS JOIN cores c LEFT JOIN ranks r ON r.categoria=e.categoria GROUP BY c.cor,c.posicao,e.categoria,e.bloqueada),
todos AS(SELECT * FROM valores UNION ALL SELECT * FROM medalhas),
novas AS(SELECT jsonb_build_object('serie',serie,'categoria',categoria,'status',CASE WHEN bloqueada THEN 'pendente' ELSE 'calculado' END,'atual',
 CASE WHEN bloqueada THEN NULL ELSE jsonb_build_object('valor',CASE WHEN tempo THEN to_jsonb(valor) ELSE to_jsonb(valor::numeric) END,'contagem',contagem,'denominador',denominador,
 'fonte','Notebook · execução #111 · célula 309 rev1 · coleta própria 01/10/2026','nota','"Maratonas: coleta própria de 01/10/2026, corte até 26/09. BR/rua, ranking elegível, 42–42,2 km, status 0/homologado/concluinte e tempo positivo. PCD pela flag ou por termos explícitos de modalidade fica fora; não altera o cadastro. Dez maiores por concluintes elegíveis. Floripa permanece no volume, mas seus dez tempos abaixo de 2h suspendem toda a prova nos indicadores de desempenho e pódio até conferência da fonte. Não descartamos só os dez registros. As outras nove provas formam o pódio parcial."'::jsonb #>> '{}') END) AS item FROM todos),
comparacoes AS(SELECT x AS item FROM anterior CROSS JOIN LATERAL jsonb_array_elements(payload->'comparacoes')x WHERE x->>'serie' NOT IN(SELECT serie FROM todos) UNION ALL SELECT item FROM novas),
