 Paulo 2026 · 12/04", "valor": null}, {"rotulo": "Maratona Internacional de Floripa 2026 · 30/08", "valor": null}, {"rotulo": "1ª MARATONA E 17ª MEIA MARATONA INTERNACIONAL DE BELO HORIZONTE · 28/06", "valor": null}, {"rotulo": "Maratona Internacional do Paraná 2026 · 28/04", "valor": null}, {"rotulo": "MARATONA INTERNACIONAL DE FORTALEZA 2026 · 12/04", "valor": null}, {"rotulo": "MARATONA INTERNACIONAL DE MACEIÓ 2026 · 02/08", "valor": null}], "ressalva": "Maratonas: coleta própria de 01/10/2026, corte até 26/09. BR/rua, ranking elegível, 42–42,2 km, status 0/homologado/concluinte e tempo positivo. PCD pela flag ou por termos explícitos de modalidade fica fora; não altera o cadastro. Dez maiores por concluintes elegíveis. Floripa permanece no volume, mas seus dez tempos abaixo de 2h suspendem toda a prova nos indicadores de desempenho e pódio até conferência da fonte. Não descartamos só os dez registros. As outras nove provas formam o pódio parcial. Onze indicadores com peso igual: quantidades sub4/3/2h30 e menores mínimo/média/mediana/Top10/100/5%/10%/50%. Empate em tempo exibido compartilha posição e pula a seguinte; percentuais não pontuam. Traço em Floripa significa revisão, não zero medalhas."}]'::jsonb)x),
series AS(SELECT CASE WHEN s->>'id' IN(SELECT serie FROM todos) THEN s||jsonb_build_object('ressalva','"Maratonas: coleta própria de 01/10/2026, corte até 26/09. BR/rua, ranking elegível, 42–42,2 km, status 0/homologado/concluinte e tempo positivo. PCD pela flag ou por termos explícitos de modalidade fica fora; não altera o cadastro. Dez maiores por concluintes elegíveis. Floripa permanece no volume, mas seus dez tempos abaixo de 2h suspendem toda a prova nos indicadores de desempenho e pódio até conferência da fonte. Não descartamos só os dez registros. As outras nove provas formam o pódio parcial."'::jsonb #>> '{}') ELSE s END AS s FROM anterior CROSS JOIN LATERAL jsonb_array_elements(payload->'series')s UNION ALL SELECT x FROM definicoes)
SELECT payload||jsonb_build_object('meta',payload->'meta'||jsonb_build_object('contrato_versao',6,'maratonas',
 (SELECT jsonb_build_object('corte',dados->>'corte','coletado_em',dados->>'coletado_em','execucao',111,'celula',309,'revisao',1,
 'eventos',dados->'eventos','concluintes',dados->'concluintes','top10_concluintes',dados->'top10_soma',
 'elegiveis_podio',(SELECT provas FROM integridade),'bloqueadas',(SELECT jsonb_agg(categoria) FROM eventos WHERE bloqueada)) FROM origem)),
 'series',(SELECT jsonb_agg(s ORDER BY s->>'id') FROM series),'comparacoes',(SELECT jsonb_agg(item ORDER BY item->>'serie',item->>'categoria') FROM comparacoes),
 'conciliacao','{"pendente":0,"calculado":0,"coletado_notebook":0}'::jsonb||(SELECT jsonb_object_agg(status,n) FROM(SELECT item->>'status' AS status,count(*) AS n FROM comparacoes GROUP BY 1)t)) AS payload
 FROM anterior WHERE (SELECT count(*) FROM eventos)=10 AND (SELECT count(*) FROM novas)=200 AND (SELECT provas FROM integridade)=9
